def factorial(n):
  if n < 0:
    return "Factorial not defined for negative numbers"
  if n == 0:
    return 1
  result = 1
  for i in range(1, n + 1):
    result *= i
  return result

print(factorial(0))
print(factorial(-5))
print(factorial(5))

